atus": "draft", "id": "1b26b879-3d3c-5706-92d9-4669fc1930df", "subject_id": "c1462ce4-d615-5284-8527-7cdf8acff419", "source_id": "22d9c4d0-958d-5f27-a85c-6382dfe4b5f1"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "姚顗：其次被夹得姓名者。", "citation": "卷279·清泰元年（934；六月至七月）·zztj-v279-y0934-p050·原文件第55行", "note": "原文：帝不能决，乃置其名于琉璃瓶，夜焚香祝天，且以筋挟之，首得文纪，次得顗。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "46a10a7d-87bf-5961-8664-971f3ea81040", "subject_id": "637bd564-eafd-5383-a3e3-241fc90fcecd", "source_id": "22d9c4d0-958d-5f27-a85c-6382dfe4b5f1"}, {"subject_table": "event", "field_path": "description", "claim_text": "新卢文纪传也记废帝将清望官姓名置琉璃瓶，夜焚香祝天以筯夹取，首得卢文纪。", "citation": "《新五代史》卷五十五，段落 xin-wudaishi-b08f244b9241-p002147；EPUB电子本，纸本及异文待核", "note": "原文：廢帝因悉書清望官姓名內琉璃瓶中，夜焚香呪天，以筯挾之，首得文紀，欣然相之，；核对说明：新悉书清望官、主置所荐之名叙范围略不同；新仅首卢，不独立补次姚，原筯支持校读主筋。", "status": "draft", "id": "6fbab139-b6ab-581c-be38-8426a2460eb1", "subject_id": "47b73896-555d-589b-a589-a1cb3d649a4d", "source_id": "dc5c2298-db71-5d76-b384-3992f1937240"}, {"subject_table": "event", "field_path": "description", "claim_text": "七月辛亥卢文纪受任中书侍郎、同平章事。", "citation": "卷279·清泰元年（934；六月至七月）·zztj-v279-y0934-p050·原文件第55行", "note": "原文：秋，七月，辛亥，以文纪为中书侍郎、同平章事。；核对说明：本段仅卢实际任官；姚实际任相在后第60段八月辛未，不提前。", "status": "draft", "id": "e5b43a9f-ef65-5197-b7fe-c8dbd62789b4", "subject_id": "1f035f1e-2f95-5e57-8f07-4f5cd9a2580b", "source_id": "22d9c4d0-958d-5f27-a85c-6382dfe4b5f1"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "934年七月辛亥", "citation": "卷279·清泰元年（934；六月至七月）·zztj-v279-y0934-p050·原文件第55行", "note": "原文：秋，七月，辛亥，以文纪为中书侍郎、同平章事。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "23379dee-7331-56e5-acbc-d690718169cb", "subject_id": "1f035f1e-2f95-5e57-8f07-4f5cd9a2580b", "source_id": "22d9c4d0-958d-5f27-a85c-6382dfe4b5f1"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "卢文纪：中书侍郎、同平章事获任者。", "citation": "卷279·清泰元年（934；六月至七月）·zztj-v279-y0934-p050·原文件第55行", "note": 